def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 2:
            return min(budget, DAILY_SALARY * 0.9)
        return min(budget, DAILY_SALARY * 0.35)

    total_players = 1 + len(alive_opponents)
    expected_units = supply / float(WATER_REQ)
    scarcity = total_players - expected_units

    prev_bids = []
    desperate_opp = False
    rich_pressure = False
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 2:
            desperate_opp = True
        if opp.get('budget', 0) > budget * 1.2:
            rich_pressure = True

    highest_prev = max(prev_bids) if prev_bids else 0.0

    if hp <= 2 or no_water_days >= 2:
        target = max(DAILY_SALARY * 0.9, highest_prev + 2.0)
    elif hp <= 4 or no_water_days >= 1:
        target = max(DAILY_SALARY * 0.72, highest_prev + 1.5)
    else:
        if scarcity <= 0:
            target = DAILY_SALARY * 0.32
        elif scarcity < 1.5:
            target = DAILY_SALARY * 0.48
        else:
            target = DAILY_SALARY * 0.62

        if highest_prev > 0:
            if highest_prev >= DAILY_SALARY * 0.85:
                target = DAILY_SALARY * 0.28 if hp > 4 else DAILY_SALARY * 0.88
            else:
                target = max(target, highest_prev + 1.25)

    if desperate_opp:
        target += 3.0
    if rich_pressure and scarcity > 0.5:
        target += 2.0

    if budget < DAILY_SALARY * 0.5:
        target = min(target, budget * 0.85)

    target = max(0.0, min(float(budget), float(target)))
    return target

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context['supply'])
    day = day_context['day']

    # Alive opponents
    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append(o)

    # Yesterday bids (immediate reaction only)
    prev_bids = []
    for o in alive:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Target: ensure we can cover requirement; if supply is tight, bid more.
    # Estimate how much water we need from the auction today.
    # If supply is below 2*WATER_REQ, competition is likely higher.
    supply_factor = 1.0
    if supply <= 2.0 * WATER_REQ:
        supply_factor = 1.15
    if supply <= 1.5 * WATER_REQ:
        supply_factor = 1.30

    # Urgency: if we have gone without water recently or hp is low.
    urgency = 1.0
    if no_water_days >= 2:
        urgency = 1.35
    if hp <= 2:
        urgency = max(urgency, 1.45)
    if hp <= 1:
        urgency = max(urgency, 1.60)

    # Opponent pressure adjustment
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # If someone was bidding close to salary, they likely anticipate scarcity.
        if highest_prev_bid >= 0.85 * DAILY_SALARY:
            # Contest lightly unless we're in critical condition.
            base = 0.35 * DAILY_SALARY
            if urgency >= 1.45:
                base = 0.60 * DAILY_SALARY
            bid = base * supply_factor * urgency
        else:
            # Their bids were not extreme; we can take a stronger position.
            # Use a floor related to our requirement.
            base = 0.55 * DAILY_SALARY
            bid = base * supply_factor * (0.95 + 0.15 * urgency)
            # If they were bidding very low, push more to secure water.
            lowest_prev_bid = min(prev_bids)
            if lowest_prev_bid < 0.35 * DAILY_SALARY:
                bid *= 1.10
    else:
        # No trace bids: default to requirement-driven moderate bid.
        base = 0.50 * DAILY_SALARY
        bid = base * supply_factor * (0.90 + 0.20 * urgency)

    # Convert bid to a feasible range and budget cap.
    # Bid cannot exceed our budget.
    if budget <= 0:
        return 0

    # Keep bid within [0, budget] and avoid overbidding beyond what is likely needed.
    # We cap at 0.95*DAILY_SALARY unless urgency is high.
    cap = 0.95 * DAILY_SALARY
    if urgency >= 1.45:
        cap = 1.00 * DAILY_SALARY

    bid = float(bid)
    if bid > cap:
        bid = cap
    if bid > budget:
        bid = budget
    if bid < 0:
        bid = 0

    # Discretize to integer bids (typical auction style). Ensure int conversion.
    return int(bid)

